int clone_body(int a, int b) {
    int total = 0;
    for (int i = 0; i < a; ++i) {
        if (i % 2 == 0) {
            total += i * b;
        } else {
            total -= i;
        }
        if (total > 1000) {
            total = 1000;
        }
    }
    return total;
}

